"""One-time CI bootstrap: upload private signing Secrets and install the restricted receiver."""

import argparse
import base64
import hashlib
import io
import json
import subprocess
import tarfile
from pathlib import Path


def properties(path):
    # Signing configuration generated by this repository uses key=value lines.
    result = {}
    for raw in path.read_text(encoding="iso-8859-1").splitlines():
        if not raw.strip() or raw.lstrip().startswith(("#", "!")):
            continue
        key, value = raw.split("=", 1)
        decoded = []
        position = 0
        value = value.lstrip()
        while position < len(value):
            character = value[position]
            if character == "\\":
                position += 1
                if position == len(value):
                    raise ValueError("Multiline signing properties are unsupported")
                character = value[position]
                if character == "u":
                    decoded.append(chr(int(value[position + 1 : position + 5], 16)))
                    position += 4
                else:
                    decoded.append(
                        {"n": "\n", "r": "\r", "t": "\t", "f": "\f"}.get(
                            character, character
                        )
                    )
            else:
                decoded.append(character)
            position += 1
        result[key.strip()] = (
            "".join(decoded).encode("utf-16", "surrogatepass").decode("utf-16")
        )
    for key in ("storeFile", "storePassword", "keyPassword", "keyAlias"):
        if not result.get(key):
            raise ValueError("Incomplete local release signing configuration")
    return result


def configure_secrets(root, repo):
    path = root / ".local/signing/release.properties"
    values = properties(path)
    keystore = Path(values["storeFile"])
    if not keystore.is_absolute():
        keystore = path.parent / keystore
    secrets = {
        "MOLLYTIME_TV_KEYSTORE_BASE64": base64.b64encode(
            keystore.read_bytes()
        ).decode(),
        "MOLLYTIME_TV_STORE_PASSWORD": values["storePassword"],
        "MOLLYTIME_TV_KEY_PASSWORD": values["keyPassword"],
        "MOLLYTIME_TV_KEY_ALIAS": values["keyAlias"],
    }
    listed = subprocess.check_output(
        ["gh", "secret", "list", "--repo", repo, "--json", "name"], text=True
    )
    existing = {item["name"] for item in json.loads(listed)}
    signing_names = set(secrets)
    if existing & signing_names and not signing_names <= existing:
        raise ValueError(
            "Partial CI signing configuration already exists; do not mix signing credentials"
        )
    if signing_names <= existing:
        print("All signing Secrets already exist; kept existing credentials.")
        return
    for name, value in secrets.items():
        # Values go through stdin, never command arguments, environment dumps or output.
        subprocess.run(
            ["gh", "secret", "set", name, "--repo", repo],
            input=value,
            text=True,
            check=True,
            capture_output=True,
        )
        print("Configured Secret: " + name)


def install_receiver(root, host, identity):
    content = io.BytesIO()
    names = {
        "mollytime-deploy.py": "infra/github-deploy.py",
        "mollytime-github-deploy": "infra/github-deploy-gate.sh",
    }
    with tarfile.open(fileobj=content, mode="w:gz") as archive:
        for name, source in names.items():
            data = (root / source).read_bytes()
            member = tarfile.TarInfo(name)
            member.size = len(data)
            member.mode = 0o755 if name.endswith("github-deploy") else 0o644
            archive.addfile(member, io.BytesIO(data))
    command = r"""set -eu
staging=$(mktemp -d /usr/local/lib/mollytime-ci.XXXXXX)
trap 'rm -rf "$staging"' EXIT
tar -xzf - -C "$staging"
python3 -m py_compile "$staging/mollytime-deploy.py"
bash -n "$staging/mollytime-github-deploy"
if [ ! -e /usr/local/lib/mollytime-deploy.py.pre-tv-ci ]; then
  cp -p /usr/local/lib/mollytime-deploy.py /usr/local/lib/mollytime-deploy.py.pre-tv-ci
fi
if [ ! -e /usr/local/sbin/mollytime-github-deploy.pre-tv-ci ]; then
  cp -p /usr/local/sbin/mollytime-github-deploy /usr/local/sbin/mollytime-github-deploy.pre-tv-ci
fi
install -m 644 "$staging/mollytime-deploy.py" /usr/local/lib/mollytime-deploy.py.next
install -m 755 "$staging/mollytime-github-deploy" /usr/local/sbin/mollytime-github-deploy.next
mv /usr/local/lib/mollytime-deploy.py.next /usr/local/lib/mollytime-deploy.py
mv /usr/local/sbin/mollytime-github-deploy.next /usr/local/sbin/mollytime-github-deploy
SSH_ORIGINAL_COMMAND=apk-state /usr/local/sbin/mollytime-github-deploy
"""
    result = subprocess.run(
        [
            "ssh",
            "-i",
            str(identity),
            "-o",
            "BatchMode=yes",
            "-o",
            "IdentitiesOnly=yes",
            "-o",
            "StrictHostKeyChecking=yes",
            "-o",
            "ConnectTimeout=15",
            "root@" + host,
            command,
        ],
        input=content.getvalue(),
        check=True,
        capture_output=True,
    )
    state = json.loads(result.stdout)
    print(
        "Installed receiver; highest published TV version: "
        + str(state["highestVersionCode"])
    )
    print(
        "Receiver source SHA-256: "
        + hashlib.sha256((root / "infra/github-deploy.py").read_bytes()).hexdigest()
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root", type=Path, default=Path(__file__).resolve().parents[1]
    )
    parser.add_argument("--repo", default="harunme/molly-time")
    parser.add_argument("--host", default="118.89.122.66")
    parser.add_argument("--identity", type=Path, default=Path("MollyTime_SSH.pem"))
    args = parser.parse_args()
    root = args.root.resolve()
    configure_secrets(root, args.repo)
    install_receiver(root, args.host, args.identity.resolve())


if __name__ == "__main__":
    main()
